using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Node3D contentVault;string contentVaultRoom="";
 static readonly string[] FieldDungeonNames={"THE FLOODED MAINTENANCE WING","THE MAKESHIFT WARD","THE SEALED RECORD STACKS","THE EMERGENCY STORES","THE ROOT CELLAR","THE RESEARCH ANNEX"};
 void DressContentDungeon(){if(!ContentEnabled||dungeon==null||InHeartRoom||InFamilyRoom)return;int theme=(int)((uint)dungeon.Id.GetHashCodeStable()%6);Color tint=theme==0?new(.25f,.43f,.44f):theme==1?new(.59f,.64f,.56f):theme==2?new(.50f,.39f,.26f):theme==3?new(.55f,.46f,.23f):theme==4?new(.30f,.40f,.24f):new(.24f,.47f,.43f);dungeonRoot.AddChild(new Label3D{Text=FieldDungeonNames[theme],Position=new(0,2.7f,3),RotationDegrees=new(0,180,0),FontSize=26,PixelSize=.008f});for(int j=0;j<5;j++){float z=-3-j*4;Tube(dungeonRoot,new(-1.6f,3.1f,z),new(1.6f,3.1f,z),.08f,Steel);if(theme is 0 or 5)Tube(dungeonRoot,new(-1.7f,2.8f,z),new(-1.7f,2.8f,z-4),.10f,tint);Box(dungeonRoot,new(1.5f,2.4f,z),new(.08f,.35f,.25f),tint);if(j%2==0)dungeonRoot.AddChild(new OmniLight3D{Position=new(0,2.7f,z),LightColor=tint.Lightened(.2f),LightEnergy=.45f,OmniRange=5});}contentVaultRoom=dungeon.Id;contentVault=new Node3D{Name="CourierSealCache",Position=new(-2,.1f,1)};dungeonRoot.AddChild(contentVault);Box(contentVault,new(0,.35f,0),new(.85f,.7f,.8f),Wood,true);Box(contentVault,new(0,.55f,-.42f),new(.16f,.18f,.025f),new(.64f,.54f,.27f));contentVault.AddChild(new Label3D{Text="COURIER SEAL / 6 FIELD RECORDS",Position=new(0,1.1f,0),FontSize=18,PixelSize=.004f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}
 bool NearContentVault()=>ContentEnabled&&dungeon!=null&&dungeon.Id==contentVaultRoom&&GodotObject.IsInstanceValid(contentVault)&&contentVault.IsInsideTree()&&Distance(player.Position,contentVault.GlobalPosition)<2.5f;
 void ContentVaultAction(){if(CoopClient||!NearContentVault())return;string key="field-vault/"+game.Save.Seed+"/"+dungeon.Id;if(game.World.Changes.OpenedSalvage.Contains(key)){game.Notice="The courier cache is empty.";return;}if(game.World.Changes.FieldSites.Count(s=>s.Read)<6){game.Notice="Recognize six field records to decipher the courier's seal / F7 field guide.";return;}if(infected.Any(e=>Distance(e.Body.Position,contentVault.GlobalPosition)<8)){game.Notice="Clear the nearby infected first.";return;}game.Change(()=>{game.World.Changes.OpenedSalvage.Add(key);game.Craft.Materials[Math.Min(6,dungeon.Tier+1)]+=3;game.Life.Medicine++;game.Career.Gain(40);game.AwardResearch("field-vault/"+dungeon.Id,2);});game.Notice="Courier cache opened / tier materials and a sealed medical kit.";FeverSync();}
}
